use strict;
use warnings;

# Read input data
open(my $fh, '<', 'data.txt') or die "Cannot open data.txt: $!";
my $data = do { local $/; <$fh> };
close($fh);

my $len = length($data);
print STDERR "Data size: $len bytes\n";

# Implement arithmetic encoder compatible with decomp.c
# The decompressor uses:
# - radix = 255
# - fraction and range for arithmetic coding
# - Adaptive context modeling with counts array

my @output_bytes;
my $bit_buffer = 0;
my $bit_count = 0;

sub write_bit {
    my ($bit) = @_;
    $bit_buffer = ($bit_buffer << 1) | ($bit ? 1 : 0);
    $bit_count++;
    if ($bit_count == 8) {
        push @output_bytes, $bit_buffer;
        $bit_buffer = 0;
        $bit_count = 0;
    }
}

sub flush_bits {
    if ($bit_count > 0) {
        $bit_buffer <<= (8 - $bit_count);
        push @output_bytes, $bit_buffer;
        $bit_buffer = 0;
        $bit_count = 0;
    }
}

# For simplicity, encode as all literals
# Each byte becomes: 0 (literal type) + sign bit + 4-bit value

# First, write the count
my $count = $len;
print STDERR "Encoding $count items as literals\n";

# Write count using get_integer format (9 bits initially)
# get_integer(9, ctx) reads until finding a 1 bit, then reads 9 more
# Result: subtract (1<<9) = 512, so value=512+actual
# For count=$len, we need to encode it
my $encoded_count = $count + (1 << 9);
print STDERR "Encoded count value: $encoded_count\n";

# Write in variable format: 1 bits until we can fit, then 9 bits
my $remaining = $encoded_count;
while ($remaining >= (1 << 9)) {
    write_bit(0);
    $remaining -= (1 << 9);
}
write_bit(1);  # Stop bit
for (my $i = 8; $i >= 0; $i--) {
    write_bit(($remaining >> $i) & 1);
}

print STDERR "After count: " . scalar(@output_bytes) . " bytes, $bit_count bits\n";

# Now encode each byte as a literal
for my $byte (unpack('C*', $data)) {
    # Write 0 bit for literal type
    write_bit(0);

    # Write sign bit (1 for negative, 0 for positive)
    # All printable ASCII is positive, so use 0
    write_bit(0);

