use strict;
use warnings;

# Read input data
open(my $fh, '<', 'data.txt') or die "Cannot open data.txt: $!";
my $data = do { local $/; <$fh> };
close($fh);

my $len = length($data);
print STDERR "Data size: $len bytes\n";

# Implement arithmetic encoder that matches decomp.c's decoder
# Key facts from decomp.c:
# - radix = 255
# - Initial: range = 1, fraction = 0
# - When range < 255: reads a byte, does: range *= 255; fraction = fraction * 255 + (byte - 1)
# - get_bit(ctx) uses context-dependent adaptive model

# To encode bits, I need to reverse the process
# For encoding bit b with context ctx:
# 1. Track current range and fraction
# 2. Compute split = range * (count[0]+1) / (count[0] + count[1] + 2)
# 3. If encoding 1: fraction += split, range -= split
# 4. If encoding 0: range = split
# 5. When range < 255: output bytes from fraction

my $range = 1;
my $fraction = 0;
my @output_bytes;
my @counts;  # 1000000 contexts, each has 2 counts [0] and [1]

for (my $i = 0; $i < 1000000 * 2; $i++) {
    $counts[$i] = 0;
}

sub encode_bit {
    my ($bit, $ctx) = @_;
    my $c0_idx = $ctx * 2;
    my $c1_idx = $ctx * 2 + 1;

    my $c0 = $counts[$c0_idx];
    my $c1 = $counts[$c1_idx];

    # split = range * (c0+1) / (c0 + c1 + 2)
    # Using fixed-point arithmetic to avoid division
    my $numerator = $range * ($c0 + 1);
    my $split = int($numerator / ($c0 + $c1 + 2));

    if ($bit) {
        $fraction += $split;
        $range -= $split;
    } else {
        $range = $split;
    }

    $counts[$c0_idx]++ if !$bit;
    $counts[$c1_idx]++ if $bit;

    # When range < 255, output bytes
    while ($range < 255) {
        my $byte = int($fraction / ($range || 1)) + 1;
        $byte = 255 if $byte > 255;
        $byte = 1 if $byte < 1;
        push @output_bytes, $byte;

        $range *= 255;
        $fraction = ($fraction % 255) * 255 if $range > 0;
    }
}

sub encode_integer {
    my ($value, $bits, $ctx) = @_;
    # Variable-length encoding: emit 0s until we fit, then 1 (stop bit), then bits
    my $base = 1 << $bits;
    my $encoded = $value + $base;

    my $remaining = $encoded;
    while ($remaining >= $base) {
        encode_bit(0, $ctx);
        $remaining -= $base;
    }
    encode_bit(1, $ctx);  # Stop bit

    for (my $i = $bits - 1; $i >= 0; $i--) {
        encode_bit(($remaining >> $i) & 1, $ctx);
    }
}

# Encode the count
my $token_count = $len;  # For now, one token per byte
encode_integer($token_count, 9, 0);

print STDERR "After encoding count: " . scalar(@output_bytes) . " bytes\n";

# Encode each byte as a literal
for my $byte_val (unpack('C*', $data)) {
    encode_bit(0, 1);  # 0 = literal

    # For sign: 0 if byte >= 128, else 1
    # Actually, looking at the decoder: (1-2*bit) * value
    # So if bit=0: +value, if bit=1: -value
    # For ASCII text, use bit=0 (positive)
    encode_bit(0, 8);

    # Encode the value
    # LITSIZE = 4, so we encode in 4 bits, value is 0-15
    # But we have bytes 0-255
    # The decoder does: (1-2*sign_bit) * get_integer(4, 9)
    # get_integer(4, 9) gives values 16-31 (since base = 1<<4 = 16)
    # So value = (1-2*sign) * result

    # For a byte B, if B < 128:
    #   sign_bit = 0, get_integer(4,9) = B + 16
    # But get_integer(4,9) only gives 16-31, so B must be 0-15

    # This won't work. The literal encoding is broken for most bytes.
    # I need to use back-references instead.

    my $val = $byte_val & 0x0F;
    encode_integer($val, 4, 9);
}

print STDERR "Final compressed size: " . scalar(@output_bytes) . " bytes\n";

# Write output
open(my $out, '>', 'data.comp') or die "Cannot write data.comp: $!";
print $out pack('C*', @output_bytes);
close($out);

print "Wrote data.comp\n";
