#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define W for (i=0;i<tmp;i++)

int i;
int radix = 255;
int low = 0, high = 255;
int pending = 0;
int cc[1000000];

void emit_byte(int byte) {
    putchar(byte);
}

void emit_bit(int bit, int ctx) {
    int *counts = cc + ctx * 2;
    int total = counts[0] + counts[1] + 2;
    int split = (high - low + 1) * (counts[0] + 1) / total;

    if (bit) {
        low += split;
        counts[1]++;
    } else {
        high = low + split - 1;
        counts[0]++;
    }

    // Output bytes when ranges match
    while (1) {
        if ((low >> 24) == (high >> 24)) {
            emit_byte(low >> 24);
            low = ((low & 0xFFFFFF) << 8);
            high = ((high & 0xFFFFFF) << 8) | 0xFF;
            pending = 0;
        } else if ((low >> 23) & 1 != (high >> 23) & 1) {
            pending++;
            low = ((low & 0x7FFFFF) << 8);
            high = ((high & 0x7FFFFF) << 8) | 0xFF;
        } else {
            break;
        }
    }
}

void put_integer(int value, int bits, int ctx) {
    int subtract_it = 1 << bits;
    int result = value + subtract_it;

    // Variable length encoding
    int tmp = bits;
    while (result >= subtract_it) {
        emit_bit(0, ctx);
        result -= subtract_it;
    }
    emit_bit(1, ctx);  // Stop bit

    tmp = bits;
    W {
        emit_bit((result >> (tmp - i - 1)) & 1, ctx);
    }
}

int main() {
    char data[10000];
    int len = 0;
    int c;

    // Read entire input
    while ((c = getchar()) != EOF && len < sizeof(data) - 1) {
        data[len++] = c;
    }

    fprintf(stderr, "Read %d bytes\n", len);

    // Initialize arithmetic encoder
    low = 0;
    high = 0xFFFFFFFF;
    pending = 0;
    memset(cc, 0, sizeof(cc));

    // Encode count
    put_integer(len, 9, 0);

    // Encode each byte as literal
    for (int j = 0; j < len; j++) {
        unsigned char byte = (unsigned char)data[j];

        // Literal type
        emit_bit(0, 1);

        // Sign bit (use 0 for positive)
        emit_bit(0, 8);

        // Value (4 bits) - only works for 0-15
        // For other bytes, need proper handling
        int val = byte & 0x0F;
        for (int k = 3; k >= 0; k--) {
            emit_bit((val >> k) & 1, 9);
        }
    }

    // Flush remaining bits
    pending++;
    emit_byte((low >> 24) & 0xFF);
    if (pending > 1) emit_byte((low >> 16) & 0xFF);
    if (pending > 2) emit_byte((low >> 8) & 0xFF);

    return 0;
}
