use strict;
use warnings;

open(my $fh, '<', 'data.txt') or die;
my $data = do { local $/; <$fh> };
close($fh);

my $len = length($data);
print STDERR "Data: $len bytes\n";

# Arithmetic encoder
my @output_bytes;
my $low = 0;
my $high = 0xFFFFFFFF;
my @cc;

sub output_bit {
    my ($bit, $ctx) = @_;
    my $c0 = $cc[$ctx * 2] // 0;
    my $c1 = $cc[$ctx * 2 + 1] // 0;
    my $range = $high - $low + 1;
    my $split = int($range * ($c0 + 1) / ($c0 + $c1 + 2));

    if ($bit) {
        $low += $split;
        $cc[$ctx * 2 + 1]++;
    } else {
        $high = $low + $split - 1;
        $cc[$ctx * 2]++;
    }

    while ((($low ^ $high) & 0xFF000000) == 0) {
        push @output_bytes, (($low >> 24) & 0xFF);
        $low = (($low << 8) & 0xFFFFFFFF);
        $high = (($high << 8) | 0xFF) & 0xFFFFFFFF;
    }
}

sub output_integer {
    my ($value, $bits, $ctx) = @_;
    my $base = 1 << $bits;
    my $encoded = $value + $base;
    my $tmp_ctx = $ctx * 99;
    my $tmp = $bits;
    while ($encoded >= $base) {
        output_bit(0, ++$tmp + $tmp_ctx);
        $encoded -= $base;
    }
    output_bit(1, ++$tmp + $tmp_ctx);
    $tmp--;
    for (my $i = 0; $i < $tmp; $i++) {
        output_bit(($encoded >> ($tmp - 1 - $i)) & 1, $tmp_ctx);
    }
}

# Use longest match greedy LZ77
my @tokens;
my $pos = 0;

while ($pos < $len) {
    my $best_len = 0;
    my $best_dist = 0;
    my $max_dist = 31;
    my $start = ($pos > $max_dist) ? ($pos - $max_dist) : 0;

    for (my $d = 1; $d <= $pos - $start; $d++) {
        my $mlen = 0;
        while ($mlen < 3 && $pos + $mlen < $len) {
            last if substr($data, $pos - $d + $mlen, 1) ne substr($data, $pos + $mlen, 1);
            $mlen++;
        }
        if ($mlen > $best_len) {
            $best_len = $mlen;
            $best_dist = $d;
        }
    }

    if ($best_len >= 3) {
        push @tokens, {type => "backref", dist => $best_dist - 1, len => $best_len - 1};
        $pos += $best_len;
    } else {
        my $byte = ord(substr($data, $pos, 1));
        push @tokens, {type => "literal", byte => $byte};
        $pos++;
    }
}

print STDERR "Tokens: " . scalar(@tokens) . "\n";

output_integer(scalar(@tokens), 9, 0);

for my $token (@tokens) {
    if ($token->{type} eq "backref") {
        output_bit(1, 1);
        output_integer($token->{dist}, 5, 2);
        output_integer($token->{len}, 2, 3);
    } else {
        output_bit(0, 1);
        my $byte = $token->{byte};
        output_bit(0, 8);
        output_integer($byte, 4, 9);
    }
}

push @output_bytes, (($low >> 24) & 0xFF), (($low >> 16) & 0xFF), (($low >> 8) & 0xFF), ($low & 0xFF);
print STDERR "Compressed: " . scalar(@output_bytes) . " bytes\n";

open(my $out, '>', 'data.comp') or die;
print $out pack('C*', @output_bytes);
close($out);
