sub emit_bit {
    my ($b, $ctx) = @_;
    my $c0 = ($cc[$ctx*2] //= 0);
    my $c1 = ($cc[$ctx*2+1] //= 0);
    my $r = $high - $low + 1;
    my $split = int($r * ($c0 + 1) / ($c0 + $c1 + 2));

    if ($b) {
        $low += $split;
        $cc[$ctx*2+1]++;
    } else {
        $high = $low + $split - 1;
        $cc[$ctx*2]++;
    }

    while ((($low ^ $high) & 0xFF000000) == 0) {
        push @out, (($low >> 24) & 0xFF);
        $low = (($low << 8) & 0xFFFFFFFF);
        $high = (($high << 8) | 0xFF) & 0xFFFFFFFF;
    }
}

sub emit_int {
    my ($v, $b, $ctx) = @_;
    my $base = 1 << $b;
    my $e = $v + $base;
    my $tc = $ctx * 99;
    my $t = $b;
    while ($e >= $base) {
        emit_bit(0, ++$t + $tc);
        $e -= $base;
    }
    emit_bit(1, ++$t + $tc);
    $t--;
    for (my $i = 0; $i < $t; $i++) {
        emit_bit(($e >> ($t - 1 - $i)) & 1, $tc);
    }
}

